function philosophyFromCallSheet(book: Playbook): string {
  const attack = book.plan.attack === "run"
    ? "build around a physical, run-forward attack"
    : book.plan.attack === "pass"
      ? "use the passing game to set the tempo and stretch the field"
      : "keep a balanced attack and adapt to the matchup";
  const defense = book.plan.blitz === "heavy"
    ? "on defense, bring pressure and force hurried decisions"
    : book.plan.blitz === "rare"
      ? "on defense, stay disciplined and make the offense earn space"
      : "on defense, mix pressure with sound coverage rules";
  const risk = book.plan.fourth === "aggressive"
    ? " The staff is willing to take calculated fourth-down chances."
    : " The staff generally protects field position and avoids unnecessary risks.";
  return `Offensively, ${attack}; ${defense}.${risk}`;
}

/** The playbook a coach runs in a given season, with any later chapter applied. */
export function playbookFor(id: string, year: number): Playbook | undefined {
  const b = PLAYBOOKS[id];
  if (!b) return undefined;
  if (!b.eras) return b.philosophy ? b : { ...b, philosophy: philosophyFromCallSheet(b) };
  let out: Playbook = b;
  for (const e of b.eras) {
    if (year < e.from) continue;
    out = { ...out, ...e, plan: { ...out.plan, ...e.plan }, eras: undefined } as Playbook;
  }
  return out.philosophy ? out : { ...out, philosophy: philosophyFromCallSheet(out) };
}
